"use strict";
// A pantry that hands out its shelves as objects of every kind. Its loader
// picks its part with a computed require() specifier, which scriptc does
// not compile natively, so the package runs in a Node island.
const { createRequire } = require("node:module");
const load = createRequire(__filename);
const [shelves] = ["./lib/shelves"].map((p) => load(p));

exports.stock = shelves.stock;
exports.labelled = shelves.stock;
exports.inherited = shelves.inherited;
exports.jar = shelves.jar;
exports.list = shelves.list;
exports.restock = shelves.restock;
exports.restockLoose = shelves.restock;
exports.recipe = shelves.recipe;
exports.hidden = shelves.hidden;
exports.picked = shelves.picked;
exports.watched = shelves.watched;
exports.watchedBelow = shelves.watchedBelow;
exports.locked = shelves.locked;
exports.odd = shelves.odd;
exports.remove = shelves.remove;
exports.put = shelves.put;
exports.dim = shelves.dim;
exports.visit = shelves.visit;
exports.walk = shelves.walk;
exports.notes = shelves.notes;
